          "Article 7 â€” Intelligence artificielle. Certaines fonctions de Koji utilisent des systÃ¨mes d'intelligence artificielle pour assister la formulation des demandes, la classification de travaux, l'analyse de photographies ou de justificatifs et la prÃ©paration d'estimations ou de devis. Leurs rÃ©sultats peuvent contenir des erreurs ou omissions et ne doivent pas Ãªtre considÃ©rÃ©s comme des avis techniques, fiscaux ou juridiques certifiÃ©s. Lorsqu'un utilisateur Ã©change avec un assistant automatisÃ© ou soumet un contenu Ã  une analyse par IA, cette intervention est signalÃ©e dans le parcours concernÃ©. Les prestataires et catÃ©gories de donnÃ©es concernÃ©s sont prÃ©sentÃ©s dans la politique de confidentialitÃ©.",
